# Données des dossiers des filiales (hors LIBOKÉ, déjà fait à part).
# Les textes viennent des pages officielles de www.starentreprise.com (copie dans docs/archives). Rien d'inventé :
# aucun prix, taux ni règle commerciale, sauf ceux que la page officielle de la filiale affiche déjà (Clinique : tarifs d'hébergement).
# Les fiches à remplir ne contiennent que des champs vides : le client remplit, la filiale complète.

def T(label, span=6): return ('t', label, span)
def P(label, span=4): return ('p', label, span)
def C(label, opts, span=12): return ('c', label, opts, span)
def L(label, n=3, h=8): return ('l', label, n, h)
def TAB(cols, n, lh=8.6, w=None): return ('tab', cols, n, lh, w)

CLIENT = [T('Nom et prénoms', 6), T('Entreprise / organisation (si besoin)', 6), T('Téléphone', 4), T('WhatsApp', 4), T('E-mail', 4),
          T('Adresse (quartier, rue, repère)', 8), T('Ville', 4)]
