RDV = [T('Date souhaitée', 4), T('Heure souhaitée', 4), T('Me contacter par', 4)]
CONTACT_PAR = ['WhatsApp', 'Appel', 'E-mail']

def F(titre, sous, court, sections, note=None, sig=None, reserve=None):
    return dict(titre=titre, sous=sous, court=court, sections=sections, note=note, sig=sig, reserve=reserve)

