def construire(f, H, secs, signatures, reserve):
    """Transforme les fiches déclaratives (ci-dessus) en HTML."""
    sortie = []
    def rendu(item):
        k = item[0]
        if k == 't': return H['champ'](item[1], item[2])
        if k == 'c': return H['cases'](item[1], item[2], item[3])
        if k == 'l': return H['lignes'](item[1], item[2], 12, item[3])
        if k == 'p': return H['prix'](item[1], item[2])
        if k == 'tab': return '<div style="grid-column:span 12">' + H['table'](item[1], item[2], item[3], item[4]) + '</div>'
    for form in f['forms']:
        sections = [(t, ''.join(rendu(i) for i in items)) for t, items in form['sections']]
        corps = secs(sections)
        if form['note']: corps += f'<p class="note">{form["note"]}</p>'
        sg = form['sig'] or ('Signature du client', 'Date et lieu', f'Visa et cachet {f["nom"]}')
        corps += signatures(sg[0], sg[1], sg[2], 16)
        sortie.append(dict(titre=form['titre'], sous=form['sous'], court=form['court'], corps=corps, reserve=form['reserve'] or ['N° de dossier', 'Date de réception', 'Agent']))
    return sortie
